fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 1);
        host::display::state_set(2, 90);
        host::display::state_set(3, 90);
        host::display::state_set(4, 0);
        host::display::state_set(5, 0);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(6) == 0;
    host::display::state_set(6, down);
    let score: i32 = host::display::state_get(4);
    if host::display::state_get(5) == 1 {
        host::display::clear(0x101018);
        host::display::draw_string(150, 180, "SORTED OUT", 0xff4040, 3);
        host::display::draw_string(140, 250, "CORRECT", 0x808080, 2);
        host::display::draw_number(300, 244, score, 0xffffff, 3);
        host::display::draw_string(130, 320, "TAP TO SORT AGAIN", 0x808080, 2);
        if tap { host::display::state_set(0, 0); }
    } else {
        let round: i32 = host::display::state_get(1);
        let shape: i32 = hash(round * 13) % 2;
        let mut timer: i32 = host::display::state_get(2) - 1;
        let mut limit: i32 = host::display::state_get(3);
        let mut done: i32 = 0;
        if timer <= 0 { done = 1; }
        if tap {
            let mut pick: i32 = 0;
            if host::display::pointer_x() >= w / 2 { pick = 1; }
            if pick == shape {
                host::display::state_set(4, score + 1);
                limit = limit - 3;
                if limit < 36 { limit = 36; }
                host::display::state_set(3, limit);
                host::display::state_set(1, round + 1);
                timer = limit;
            } else {
                done = 1;
            }
        }
        if done == 1 {
            host::display::state_set(5, 1);
        }
        host::display::state_set(2, timer);
        host::display::clear(0x0c0c14);
        host::display::fill_rect(0, 0, timer * w / limit, 10, 0x00ccff);
        if shape == 0 {
            host::display::fill_rect(w / 2 - 60, h / 2 - 80, 120, 120, 0xffaa00);
        } else {
            host::display::fill_triangle(w / 2 - 70, h / 2 + 40, w / 2 + 70, h / 2 + 40, w / 2, h / 2 - 80, 0x00cc88);
        }
        host::display::fill_rect(w / 2 - 1, h - 120, 2, 120, 0x303030);
        host::display::draw_string(60, h - 70, "SQUARE", 0xffaa00, 3);
        host::display::draw_string(w / 2 + 40, h - 70, "TRIANGLE", 0x00cc88, 3);
        host::display::draw_number(8, 24, score, 0xffffff, 2);
    }
    host::display::present();
}
